pub(crate) fn run_locked(
    spec: &Path,
    repository: &Path,
    options: &Options,
) -> Result<Report, String> {
    options.validate()?;
    let root =
        RootCapability::open(repository).map_err(|_| "review_invocation_root_unavailable")?;
    let mut state = task_review::state(&root, spec)?;
    if state.status != "history_review_required" {
        return Err("semantic_review_requires_pending_held_audit".into());
    }
    // Invalidate old approval before ANY fallible preparation or native probe.
    state.semantic_review_required = true;
    state.semantic_review_sha256 = None;
    state.last_artifact = Some("review-invocation.json".into());
    crate::run_task::save_state_in_repository(
        repository,
        &crate::run_task::state_file_path(repository, spec),
        &state,
    )
    .map_err(|_| "review_invocation_state_write_failed")?;
    let mut random = [0u8; 16];
    getrandom::fill(&mut random).map_err(|_| "review_invocation_random_unavailable")?;
    let mut receipt = Receipt {
        schema_version: 1,
        attempt_id: crate::hex::encode(&random),
        status: Status::Pending,
        reason: None,
        target_revision: None,
        expected_review_revision: None,
        response_sha256: None,
        submission_sha256: None,
        invocation: None,
    };
    let path = receipt_path(repository, spec);
    root.ensure_directory(path.parent().ok_or("review_invocation_path_invalid")?)
        .map_err(|_| "review_invocation_directory_unavailable")?;
    let mut journal = Journal {
        root: &root,
        path,
        last: None,
    };
    journal.publish(&receipt)?;
    let result = execute(spec, repository, &root, options, &mut receipt, &mut journal);
    match result {
        Ok(report) => Ok(report),
        Err(reason) => {
            receipt.status = Status::Failed;
            receipt.reason = Some(reason.clone());
            journal.publish(&receipt)?;
            Ok(Report::new(task_review::Status::Failed, Some(reason), None))
        }
    }
}

/// Canonical specs own `<task>/state.json`. Legacy top-level task specs retain
/// their basename-keyed location. Every other repository-contained spec uses a
/// full exact-path digest so equal basenames cannot share controller state.
pub fn state_file_path(repo_root: &Path, spec_path: &Path) -> PathBuf {
    match spec_artifact_layout(repo_root, spec_path) {
        SpecArtifactLayout::Canonical(task) => repo_root
            .join(".mastermind/tasks")
            .join(task)
            .join("state.json"),
        SpecArtifactLayout::LegacyFlat(stem) => repo_root
            .join(".mastermind/run-state")
            .join(format!("{stem}.json")),
        SpecArtifactLayout::Noncanonical(key) => repo_root
            .join(".mastermind/run-state/.noncanonical")
            .join(format!("{key}.json")),
    }
}

pub fn parse_config(source: &[u8]) -> Result<PolicyConfig, PolicyError> {
    if source.is_empty() || source.len() as u64 > CONFIG_BYTE_LIMIT {
        return Err(PolicyError::new(
            "invalid_policy_config",
            "policy config must be non-empty and no larger than 1 MiB",
        ));
    }
    let raw: RawConfig = serde_norway::from_slice(source).map_err(|error| {
        PolicyError::new(
            "invalid_policy_config",
            format!("YAML does not match the v1 policy schema: {error}"),
        )
    })?;
    if raw.version != 1 {
        return Err(PolicyError::new(
            "unsupported_policy_version",
            format!("expected version 1, found {}", raw.version),
        ));
    }
    if raw.rules.is_empty() || raw.rules.len() > RULE_LIMIT {
        return Err(PolicyError::new(
            "invalid_policy_config",
            format!("`rules` must contain between 1 and {RULE_LIMIT} entries"),
        ));
    }

    let mut ids = BTreeSet::new();
    let mut rules = Vec::with_capacity(raw.rules.len());
    for rule in raw.rules {
        validate_rule_id(&rule.id)?;
        if !ids.insert(rule.id.clone()) {
            return Err(config_error(&rule.id, "rule id is duplicated"));
        }
        if rule.action_count() != 1 {
            return Err(config_error(
                &rule.id,
                "exactly one policy action must be configured",
            ));
        }
        let kind = compile_rule(&rule)?;
        rules.push(PolicyRule { id: rule.id, kind });
    }
    rules.sort_by(|left, right| left.id.cmp(&right.id));
    Ok(PolicyConfig { version: 1, rules })
}

/// Formatter and linter scopes at `history_ref`. Without a listing only the
/// gofmt convention remains; missing configuration never fails a mine.
pub(super) fn detect(
    root: &Path,
    history_ref: &str,
    listing: Option<&str>,
) -> Result<Vec<ToolScope>, Box<dyn std::error::Error>> {
    let mut scopes = vec![scope("", GOFMT, GO, FORMATTED)];
    let Some(listing) = listing else {
        return Ok(scopes);
    };
    let mut content_paths = Vec::new();
    for path in listing.split('\0').filter(|path| !path.is_empty()) {
        let (dir, name) = match path.rsplit_once('/') {
            Some((dir, name)) => (&path[..dir.len() + 1], name),
            None => ("", path),
        };
        match name {
            "rustfmt.toml" | ".rustfmt.toml" => scopes.push(scope(dir, RUSTFMT, RUST, FORMATTED)),
            "biome.json" | "biome.jsonc" => scopes.push(scope(dir, BIOME, SCRIPT, FORMATTED)),
            "dprint.json" | ".dprint.json" => scopes.push(scope(dir, DPRINT, SCRIPT, FORMATTED)),
            ".clang-format" => scopes.push(scope(dir, CLANG_FORMAT, C_FAMILY, FORMATTED)),
            ".editorconfig" => scopes.push(scope(dir, EDITORCONFIG, ANY, INDENT)),
            "ruff.toml" | ".ruff.toml" => scopes.push(scope(dir, RUFF, PYTHON, FORMATTED)),
            name if name.starts_with(".prettierrc") || name.starts_with("prettier.config.") => {
                scopes.push(scope(dir, PRETTIER, SCRIPT, FORMATTED));
            }
            name if name.starts_with(".eslintrc") || name.starts_with("eslint.config.") => {
                scopes.push(scope(dir, ESLINT, SCRIPT, DECLARATION));
            }
            _ if wants_contents(path, name) && !path.contains('\n') => content_paths.push(path),
            _ => {}
        }
    }
    content_paths.truncate(MAX_CONTENT_READS);
    for (path, text) in read_snapshot_files(root, history_ref, &content_paths)? {
        scopes_from_contents(&path, &text, &mut scopes);
    }
    scopes.sort();
    scopes.dedup();
    Ok(scopes)
}

